// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO.Customer;
using Shared.DTO.Departments;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Department
{
    public partial class Create
    {
        DepartmentDto department { get; set; } = new DepartmentDto();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected async Task AddDepartment()
        {
            var response = await Http.PostAsJsonAsync("api/Departments", department);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/Department");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }

        }
    }
}
